@pretty_log
def make_l3_call_on_cell_if_requested(cell: CloudCell,
                                      caller: CallManager,
                                      throughputs: Union[Dict, None],
                                      ue_network_modes: Union[Dict[str, str], None],
                                      logs_path: str,
                                      expect_attach: bool = True,
                                      prepare_cells: bool = True,
                                      duration: str = '30s',
                                      protocol: str = 'udp',
                                      udp_buffer: str = '4M'):
    """
    Performs L3 call on given Cell if throughputs are provided.
    :param cell: Cloud RAN Cell on which L3 call should be made
    :param caller: call manager which will handle L3 call procedure
    :param throughputs: throughput and deviation values for each Cell identified by its nrCellIdentity for NR Cells,
                        eutranCellId for LTE Cells, wnCelId for WCDMA Cells;
                        i.e.:
                        {'827736065': {'throughput': {'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'},
                                       'deviation': '90%'}}
                        if None provided then L3 call will not be performed
    :param ue_network_modes: UE serial numbers paired with desired network modes;
                             i.e. {'HZQN1876AAK90100042': 'NR_only',
                                   'M6AIKN009217SWX': 'LTE_only'}
                             possible UE network modes: 'NR_only', 'LTE_only', 'NR_LTE';
                             when using more than one UE please make sure that modes you choose are either all
                             with '_only' suffix or all are 'NR_LTE' as it is not yet possible to mix those.
                             this param is mandatory for SA+NSA mode;
                             if None provided then network mode will not be changed on any UE
    :param logs_path: path to the directory where logs from L3 call will be stored
    :param expect_attach: determines whether to expect attach to be possible (True) or not possible (False);
                          defaults to True (attach should be possible)
    :param prepare_cells: determines whether to prepare Cells for L3 call;
                          if so: all Cells apart from the called one will be either barred or blocked;
                          defaults to True (Cells will be prepared)
    :param duration: duration (in seconds) of the data transfer during L3 call; defaults to 30 seconds
    :param protocol: protocol used for data transfer during L3 call; defaults to 'udp'
    :param udp_buffer: monitoring data buffer; defaults to 4M
    """
    if throughputs:
        if prepare_cells:
            cell.rmod.du.allow_alarm(fault_id='49',
                                     fault_name='Cell blocked')

        caller.configure_env(logs_path=logs_path,
                             ue_network_modes=ue_network_modes)
        caller.make_l3_call(called_cell=cell.config_dist_name,
                            attach_should_be_possible=expect_attach,
                            prepare_cells_to_call=prepare_cells,
                            duration=duration if expect_attach else '',
                            throughput=throughputs,
                            protocol=protocol,
                            udp_buffer=udp_buffer)
        caller.clean_up_env()

        if prepare_cells:
            cell.rmod.du.disallow_alarm(fault_id='49',
                                        fault_name='Cell blocked')
    else:
        log_debug(f'No throughputs provided, L3 call on {cell.name} has been skipped')


@pretty_log
def make_l3_call_in_background_on_cell_if_requested(cell: CloudCell,
                                                    caller: CallManager,
                                                    direction: str,
                                                    throughputs: Union[Dict, None],
                                                    ue_network_modes: Union[Dict[str, str], None],
                                                    logs_path: str,
                                                    prepare_cells: bool = True,
                                                    ignored_cells_on_preparation: Union[List[CloudCell], None] = None,
                                                    duration: str = '30s',
                                                    protocol: str = 'udp',
                                                    udp_buffer: str = '4M'):
    """
    Performs L3 call in background on given Cell if throughputs are provided.
    :param cell: Cloud RAN Cell on which L3 call in background should be made
    :param caller: call manager which will handle L3 call procedure
    :param direction: direction in which data transfer should be performed, 'UL', 'DL' or 'UL_DL'
    :param throughputs: throughput and deviation values for each Cell identified by its nrCellIdentity for NR Cells,
                        eutranCellId for LTE Cells, wnCelId for WCDMA Cells;
                        i.e.:
                        {'827736065': {'throughput': {'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'},
                                       'deviation': '90%'}}
                        if None provided then L3 call will not be performed
    :param ue_network_modes: UE serial numbers paired with desired network modes;
                             i.e. {'HZQN1876AAK90100042': 'NR_only',
                                   'M6AIKN009217SWX': 'LTE_only'}
                             possible UE network modes: 'NR_only', 'LTE_only', 'NR_LTE';
                             when using more than one UE please make sure that modes you choose are either all
                             with '_only' suffix or all are 'NR_LTE' as it is not yet possible to mix those.
                             this param is mandatory for SA+NSA mode;
                             if None provided then network mode will not be changed on any UE
    :param logs_path: path to the directory where logs from L3 call will be stored
    :param prepare_cells: determines whether to prepare Cells for L3 call;
                          if so: all Cells apart from the called one will be either barred or blocked;
                          defaults to True (Cells will be prepared)
    :param ignored_cells_on_preparation: list of cells that should be ignored during background L3 Call not called cells
                                         preparation procedure and not be blocked/barred; if None provided then all not
                                         called cells will be prepared; defaults to None
    :param duration: duration (in seconds) of the data transfer during L3 call; defaults to 30 seconds
    :param protocol: protocol used for data transfer during L3 call; defaults to 'udp'
    :param udp_buffer: monitoring data buffer; defaults to 4M
    """
    if throughputs:
        if prepare_cells:
            cell.rmod.du.allow_alarm(fault_id='49',
                                     fault_name='Cell blocked')

        caller.configure_env(logs_path=logs_path,
                             ue_network_modes=ue_network_modes)

        if ignored_cells_on_preparation:
            ignored_cells_on_preparation = [
                ignored_cell.config_dist_name for ignored_cell in ignored_cells_on_preparation]

        log_info(f'Starting background L3 Call to cell: {cell.config_dist_name}, attach should be possible.',
                 to_console=True)
        caller.start_data_transfer_in_background(direction=direction,
                                                 duration=duration,
                                                 throughput=throughputs,
                                                 protocol=protocol,
                                                 udp_buffer=udp_buffer,
                                                 prepare_cells_to_call=prepare_cells,
                                                 called_cell=cell.config_dist_name,
                                                 ignored_cells_on_preparation=ignored_cells_on_preparation)

    else:
        log_debug(f'No throughputs provided, background L3 call on {cell.name} has been skipped')


@pretty_log
def verify_results_for_l3_call_in_background_on_cell_if_requested(cell: CloudCell,
                                                                  caller: CallManager,
                                                                  throughputs: Union[Dict, None]):
    """
    Waits for background data transfer (that's started by 'make_l3_call_in_background_on_cell_if_requested' method)
    to end. Method is responsible for performing UE detach, stopping log collection and verifying L3 call procedure
    results.
    :param cell: Cloud RAN Cell on which L3 call in background was started
    :param caller: call manager which handles L3 call procedure
    :param throughputs: throughput and deviation values for each Cell identified by its nrCellIdentity for NR Cells,
                        eutranCellId for LTE Cells, wnCelId for WCDMA Cells;
                        i.e.:
                        {'827736065': {'throughput': {'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'},
                                       'deviation': '90%'}}
                        if None provided then L3 call in background teardown will not be performed
    """
    if throughputs:
        log_info(f'Waiting for background L3 Call to cell: {cell.config_dist_name} to end, then performing detach,'
                 f' stopping log collection and verifying results',
                 to_console=True)
        caller.wait_for_background_data_transfer_to_end(called_cell=cell.config_dist_name)

        caller.clean_up_env()

        cell.rmod.du.disallow_alarm(fault_id='49',
                                    fault_name='Cell blocked')
    else:
        log_debug(f'No throughputs provided, waiting for data transfer to end and verifying results for background '
                  f'L3 call on {cell.name} has been skipped')


@pretty_log
def make_l3_call_on_each_rmod_cell_if_requested(rmod: CloudRmod,
                                                caller: CallManager,
                                                throughputs: Union[Dict, None],
                                                ue_network_modes: Dict[str, str],
                                                logs_path: str,
                                                errors: ErrorHistory,
                                                expect_attach: bool = True,
                                                prepare_cells: bool = True,
                                                duration: str = '30s',
                                                protocol: str = 'udp',
                                                udp_buffer: str = '4M'):
    """
    Performs L3 call on each Cell from given RMOD if throughputs are provided.
    :param rmod: Cloud RAN RMOD on which L3 call should be made
    :param caller: call manager which will handle L3 call procedure
    :param throughputs: throughput and deviation values for each Cell identified by its nrCellIdentity for NR Cells,
                        eutranCellId for LTE Cells, wnCelId for WCDMA Cells;
                        i.e.:
                        {'827736065': {'throughput': {'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'},
                                       'deviation': '90%'}}
                        if None provided then L3 call will not be performed
    :param ue_network_modes: UE serial numbers paired with desired network modes;
                             i.e. {'HZQN1876AAK90100042': 'NR_only',
                                   'M6AIKN009217SWX': 'LTE_only'}
                             possible UE network modes: 'NR_only', 'LTE_only', 'NR_LTE';
                             when using more than one UE please make sure that modes you choose are either all
                             with '_only' suffix or all are 'NR_LTE' as it is not yet possible to mix those.
                             this param is mandatory for SA+NSA mode;
                             if None provided then network mode will not be changed on any UE
    :param logs_path: path to the directory where logs from L3 call will be stored
    :param errors: history of errors occurred during test execution;
                   used to store errors that occurred during L3 call procedure for later verification
    :param expect_attach: determines whether to expect attach to be possible (True) or not possible (False);
                          defaults to True (attach should be possible)
    :param prepare_cells: determines whether to prepare Cells for L3 call;
                          if so: all Cells apart from the called one will be either barred or blocked;
                          defaults to True (Cells will be prepared)
    :param duration: duration (in seconds) of the data transfer during L3 call; defaults to 30 seconds
    :param protocol: protocol used for data transfer during L3 call; defaults to 'udp'
    :param udp_buffer: monitoring data buffer; defaults to 4M
    """
    if throughputs:
        if prepare_cells:
            rmod.du.allow_alarm(fault_id='49',
                                fault_name='Cell blocked')

        caller.configure_env(logs_path=logs_path,
                             ue_network_modes=ue_network_modes)

        for cell in rmod.cells:
            _try_to_make_l3_call_on_cell(cell,
                                         caller,
                                         throughputs,
                                         expect_attach,
                                         prepare_cells,
                                         duration,
                                         protocol,
                                         udp_buffer,
                                         errors)

        caller.clean_up_env()

        if prepare_cells:
            rmod.du.disallow_alarm(fault_id='49',
                                   fault_name='Cell blocked')
    else:
        log_debug(f'No throughputs provided, L3 call on each {rmod.name} Cell has been skipped')


