@pretty_log
def _try_to_make_l3_call_on_cell(cell: CloudCell,
                                 caller: CallManager,
                                 throughputs: Dict,
                                 expect_attach: bool,
                                 prepare_cells: bool,
                                 duration: str,
                                 protocol: str,
                                 udp_buffer: str,
                                 errors: ErrorHistory):
    try:
        caller.make_l3_call(called_cell=cell.config_dist_name,
                            attach_should_be_possible=expect_attach,
                            prepare_cells_to_call=prepare_cells,
                            duration=duration if expect_attach else '',
                            throughput=throughputs,
                            protocol=protocol,
                            udp_buffer=udp_buffer)
    except (CannotAttachError,
            AttachMsgsFoundInPcap,
            DataTransferVerificationFailure) as exc:
        errors.add(error_type='L3 call failed',
                   error_msg=f'Error occurred while making L3 call on {cell.name}: {exc}')
